import{_ as a,o as s,c as i,a3 as t}from"./chunks/framework.DMtjdCb-.js";const k=JSON.parse('{"title":"2. Linux・Docker に導入","description":"","frontmatter":{},"headers":[],"relativePath":"ja/docker.md","filePath":"ja/docker.md"}'),o={name:"ja/docker.md"};function n(l,e,r,d,c,h){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="_2-linux・docker-に導入" tabindex="-1">2. Linux・Docker に導入 <a class="header-anchor" href="#_2-linux・docker-に導入" aria-label="Permalink to &quot;2. Linux・Docker に導入&quot;">​</a></h1><p>標準構成では、操作画面の AnimeMachine、購読用の Ani-RSS、ダウンロード用の qBittorrent、検索用の Torrent Collector が起動します。初回の接続とアカウント設定は自動で行われます。</p><h2 id="プロジェクト用フォルダーを作る" tabindex="-1">プロジェクト用フォルダーを作る <a class="header-anchor" href="#プロジェクト用フォルダーを作る" aria-label="Permalink to &quot;プロジェクト用フォルダーを作る&quot;">​</a></h2><ol><li>使用する Linux に <a href="https://docs.docker.com/engine/install/" target="_blank" rel="noreferrer">Docker Engine</a> と <a href="https://docs.docker.com/compose/install/" target="_blank" rel="noreferrer">Compose プラグイン</a>を導入します。Docker Engine 24+、Compose 2.20.3+ を使用します。</li><li>AnimeMachine を動かす PC・サーバーでターミナルを開きます。</li><li>動画を保存する空き容量のあるディスクに、固定のプロジェクトフォルダーを作成します。</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/animemachine</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/animemachine</span></span></code></pre></div><p>このフォルダー内に <code>config</code>、<code>data</code>、<code>library</code>、<code>torrents</code>、<code>external</code> などが作成されます。動画は <code>library</code> または <code>external/ani-rss</code> に保存されるため、空き容量のあるディスクを選びます。</p><h2 id="compose-ファイルを取得する" tabindex="-1">Compose ファイルを取得する <a class="header-anchor" href="#compose-ファイルを取得する" aria-label="Permalink to &quot;Compose ファイルを取得する&quot;">​</a></h2><p><a href="/help/downloads/compose.yaml" download="compose.yaml">compose.yaml をダウンロード</a>し、先ほどのフォルダーへ保存します。GitHub のファイル画面では <strong>Download raw file</strong> を選びます。ファイル名は <strong><code>compose.yaml</code></strong> のままにします。ターミナルからも取得できます。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/kyupi-git/animemachine/main/deploy/compose/compose.yaml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose.yaml</span></span></code></pre></div><p>この一つのファイルで全サービスを起動できます。初回起動前に、各サービスのアカウントや設定ファイルを用意する必要はありません。</p><h2 id="ターミナルから起動する" tabindex="-1">ターミナルから起動する <a class="header-anchor" href="#ターミナルから起動する" aria-label="Permalink to &quot;ターミナルから起動する&quot;">​</a></h2><p><code>compose.yaml</code> を保存したフォルダーで実行します。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>状態を確認します。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span></code></pre></div><p><strong>確認する状態：</strong> 四つのサービスが実行中になります。Ani-RSS と Collector は AnimeMachine の準備を待って起動します。初回のコマンド実行中は、イメージの取得状況が表示されます。</p><h2 id="ページを開いてパスワードを確認する" tabindex="-1">ページを開いてパスワードを確認する <a class="header-anchor" href="#ページを開いてパスワードを確認する" aria-label="Permalink to &quot;ページを開いてパスワードを確認する&quot;">​</a></h2><ol><li>下記のコマンドで、初期アカウントとランダムパスワードを確認します。</li><li>同じ PC では <strong><a href="http://localhost:8787" target="_blank" rel="noreferrer">http://localhost:8787</a></strong> を開きます。別の端末では、サーバーの LAN アドレスを使います。例は <code>http://192.168.1.20:8787</code> です。</li><li>ログインし、<a href="./first-use.html">初回ログイン</a>へ進みます。</li></ol><p>起動ログを確認します。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> animemachine</span></span></code></pre></div><table tabindex="0"><thead><tr><th>管理画面</th><th>LAN 内のアドレス</th></tr></thead><tbody><tr><td>AnimeMachine</td><td><code>http://NASのアドレス:8787</code></td></tr><tr><td>Ani-RSS</td><td><code>http://NASのアドレス:7789</code></td></tr><tr><td>qBittorrent</td><td><code>http://NASのアドレス:8080</code></td></tr></tbody></table><p>日常の操作は AnimeMachine から行えます。他の管理画面を開く場合、ユーザー名は <code>admin</code>、初期パスワードはプロジェクト内の <code>config/ani-rss/.animemachine/web-password</code>、<code>config/qbittorrent/.animemachine/web-password</code> に保存されています。</p><h2 id="既存サービスや別のディスクを使う" tabindex="-1">既存サービスや別のディスクを使う <a class="header-anchor" href="#既存サービスや別のディスクを使う" aria-label="Permalink to &quot;既存サービスや別のディスクを使う&quot;">​</a></h2><p>すでに Ani-RSS・qBittorrent がある場合は <a href="https://github.com/kyupi-git/animemachine/tree/main/deploy/compose/templates" target="_blank" rel="noreferrer">01・02 テンプレート</a>を選び、<strong>設定 → 接続</strong> から登録できます。標準ファイルと各テンプレートは代替構成なので、一つを選んで導入します。</p><p>別のディスクにある動画は<a href="./collections.html#docker-folders">フォルダーの対応</a>を設定します。フル構成では公開配信元への接続を確認し、必要に応じて利用可能な代替先を選びます。</p><h2 id="この手順で困ったら" tabindex="-1">この手順で困ったら <a class="header-anchor" href="#この手順で困ったら" aria-label="Permalink to &quot;この手順で困ったら&quot;">​</a></h2><ul><li><strong>設定ファイルが見つからない：</strong> <code>compose.yaml</code> のある場所でコマンドを実行し、名前が <code>compose.yaml.txt</code> になっていないか確認します。</li><li><strong>イメージ取得に失敗：</strong> Docker のエラーを確認し、接続復旧後に同じコマンドを再実行します。取得済みのレイヤーは再利用されます。</li><li><strong>Docker の権限エラー：</strong> Docker を操作できるアカウントを使用します。管理者権限が必要な構成では、Docker のコマンドに <code>sudo</code> を付けます。</li><li><strong>ポートが使用中：</strong> 同じ場所の <code>.env</code> に <code>ANM_WEB_PORT=8788</code> などの空きポートを指定して再起動します。ブラウザー側も 8788 を使用します。</li><li><strong>一時停止したい：</strong> <code>docker compose stop</code> を実行します。設定・記録・動画は保存されたままです。</li></ul>`,27)])])}const g=a(o,[["render",n]]);export{k as __pageData,g as default};
